def unique_jobs(rows):
    seen = set()
    result = []
    for r in rows:
        source = r['source']
        source_id = r['source_id']
        # Check if source_id is missing/None/empty
        if source_id is None or source_id == '':
            result.append(r)
        else:
            key = (source, source_id)
            if key in seen:
                continue
            seen.add(key)
            result.append(r)
    return result
